-- ADR-1501: mediadores para Visita e conferência da ponte legada.
do $migracao$
declare d text:=pg_catalog.pg_get_functiondef('pcm.sso_listar_versoes_conferencia_legado(uuid,uuid,integer,integer)'::regprocedure);a text;b text;
begin
 a:='select habilitado from pcm.sso_relacao_plano_legado_gate where id';b:='select g.habilitado from pcm.sso_relacao_plano_legado_gate g where g.id';
 if (length(d)-length(replace(d,a,'')))/length(a)<>1 then raise exception 'definicao_lista_versoes_incompativel' using errcode='55000';end if;d:=replace(d,a,b);
 a:='select 1 from pcm.planos_manutencao where id=p_plano_id and cliente_id=p_cliente_id';b:='select 1 from pcm.planos_manutencao pl where pl.id=p_plano_id and pl.cliente_id=p_cliente_id';
 if (length(d)-length(replace(d,a,'')))/length(a)<>1 then raise exception 'definicao_plano_versoes_incompativel' using errcode='55000';end if;execute replace(d,a,b);
end; $migracao$;
create function pcm.sso_exigir_visita_ponte(p_ator uuid,p_cliente uuid,p_escrita boolean) returns void language plpgsql volatile security definer set search_path='' as $$
begin perform pcm.sso_conferir_ponte_legada_mediada(p_ator,p_cliente,p_escrita);if config.sso_autorizar_acao('visita.confirmar',p_cliente) is distinct from true then raise exception 'sem_acesso' using errcode='42501';end if;end; $$;
revoke all on function pcm.sso_exigir_visita_ponte(uuid,uuid,boolean) from public,anon,authenticated,service_role;
create function pcm.sso_visitas_legadas_mediadas(p_ator_id uuid,p_cliente_id uuid,p_plano_id uuid,p_legado_id uuid,p_relacao_request_id uuid,p_apos uuid,p_limite integer) returns table(preparada_id uuid,visita_id uuid,serie_id uuid,semana_origem date,vencimento_original date,alvo_tipo text,alvo_id uuid) language plpgsql volatile security definer set search_path='' as $$
begin perform pcm.sso_exigir_visita_ponte(p_ator_id,p_cliente_id,false);return query select * from pcm.sso_listar_visitas_integracao_legado(p_cliente_id,p_plano_id,p_legado_id,p_relacao_request_id,p_apos,p_limite);perform pcm.sso_exigir_visita_ponte(p_ator_id,p_cliente_id,false);end; $$;
create function pcm.sso_materializar_visita_legada_mediada(p_ator_id uuid,p_request_id uuid,p_cliente_id uuid,p_preparada_id uuid,p_plano_legado_id uuid,p_relacao_request_id uuid,p_motivo text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare r jsonb;begin perform pcm.sso_exigir_visita_ponte(p_ator_id,p_cliente_id,true);r:=pcm.sso_materializar_visita_legado(p_request_id,p_cliente_id,p_preparada_id,p_plano_legado_id,p_relacao_request_id,p_motivo);perform pcm.sso_exigir_visita_ponte(p_ator_id,p_cliente_id,false);return r;end; $$;
create function pcm.sso_lote_visita_legada_mediado(p_ator_id uuid,p_request_id uuid,p_cliente_id uuid,p_plano_id uuid,p_legado_id uuid,p_relacao_id uuid,p_preparadas jsonb,p_motivo text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare r jsonb;begin perform pcm.sso_exigir_visita_ponte(p_ator_id,p_cliente_id,true);r:=pcm.sso_materializar_lote_visita_legado(p_request_id,p_cliente_id,p_plano_id,p_legado_id,p_relacao_id,p_preparadas,p_motivo);perform pcm.sso_exigir_visita_ponte(p_ator_id,p_cliente_id,false);return r;end; $$;
create function pcm.sso_versoes_legadas_mediadas(p_ator_id uuid,p_cliente_id uuid,p_plano_id uuid,p_apos integer,p_limite integer) returns table(id uuid,numero integer,estado text) language plpgsql volatile security definer set search_path='' as $$
begin perform pcm.sso_conferir_ponte_legada_mediada(p_ator_id,p_cliente_id,false);return query select * from pcm.sso_listar_versoes_conferencia_legado(p_cliente_id,p_plano_id,p_apos,p_limite);perform pcm.sso_conferir_ponte_legada_mediada(p_ator_id,p_cliente_id,false);end; $$;
create function pcm.sso_conferencia_legada_mediada(p_ator_id uuid,p_cliente_id uuid,p_plano_id uuid,p_versao_id uuid,p_legado_id uuid,p_apos uuid,p_limite integer) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare r jsonb;begin perform pcm.sso_conferir_ponte_legada_mediada(p_ator_id,p_cliente_id,false);r:=pcm.sso_conferir_relacao_plano_legado(p_cliente_id,p_plano_id,p_versao_id,p_legado_id,p_apos,p_limite);perform pcm.sso_conferir_ponte_legada_mediada(p_ator_id,p_cliente_id,false);return r;end; $$;
create function pcm.sso_comparacao_legada_mediada(p_ator_id uuid,p_cliente_id uuid,p_plano_id uuid,p_versao_id uuid,p_rotina_id uuid,p_legado_id uuid,p_inicio date,p_fim date) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare r jsonb;begin perform pcm.sso_conferir_ponte_legada_mediada(p_ator_id,p_cliente_id,false);r:=pcm.sso_comparar_calendario_legado(p_cliente_id,p_plano_id,p_versao_id,p_rotina_id,p_legado_id,p_inicio,p_fim);perform pcm.sso_conferir_ponte_legada_mediada(p_ator_id,p_cliente_id,false);return r;end; $$;
revoke all on function pcm.sso_visitas_legadas_mediadas(uuid,uuid,uuid,uuid,uuid,uuid,integer),pcm.sso_materializar_visita_legada_mediada(uuid,uuid,uuid,uuid,uuid,uuid,text),pcm.sso_lote_visita_legada_mediado(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,text),pcm.sso_versoes_legadas_mediadas(uuid,uuid,uuid,integer,integer),pcm.sso_conferencia_legada_mediada(uuid,uuid,uuid,uuid,uuid,uuid,integer),pcm.sso_comparacao_legada_mediada(uuid,uuid,uuid,uuid,uuid,uuid,date,date) from public,anon,authenticated,service_role;
grant execute on function pcm.sso_visitas_legadas_mediadas(uuid,uuid,uuid,uuid,uuid,uuid,integer),pcm.sso_materializar_visita_legada_mediada(uuid,uuid,uuid,uuid,uuid,uuid,text),pcm.sso_lote_visita_legada_mediado(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,text),pcm.sso_versoes_legadas_mediadas(uuid,uuid,uuid,integer,integer),pcm.sso_conferencia_legada_mediada(uuid,uuid,uuid,uuid,uuid,uuid,integer),pcm.sso_comparacao_legada_mediada(uuid,uuid,uuid,uuid,uuid,uuid,date,date) to authenticated;
